function HouseScene({ carPresent = true, charging = true, gridOverloaded = false }) {
  const effectiveCharging = carPresent && charging
  const litWindows = carPresent ? WINDOWS_LIT.carPresent : WINDOWS_LIT.carAbsent

  return (
    <svg
      className="house-scene"
      viewBox="0 0 1765 1330"
      xmlns="http://www.w3.org/2000/svg"
      style={{ fillRule: 'nonzero', clipRule: 'evenodd', strokeLinecap: 'round', strokeLinejoin: 'round' }}
    >
      {/* === Parking space (static) === */}
      <path d={PATHS[0]} fill="#2c521e" />
      {/* === Neighbourhood (static, multi-coloured) === */}
      <g>
        <path d={PATHS[1]} fill="#000000" />
        <path d={PATHS[2]} fill="#836212" />
        <path d={PATHS[3]} fill="#836212" />
        <path d={PATHS[4]} fill="#836212" />
        <path d={PATHS[5]} fill="#836212" />
        <path d={PATHS[6]} fill="#836212" />
        <path d={PATHS[7]} fill="#836212" />
        <path d={PATHS[8]} fill="#eda18b" />
        <path d={PATHS[9]} fill="#ed6d48" />
        <path d={PATHS[10]} fill="#ed6d48" />
        <path d={PATHS[11]} fill="#eda18b" />
        <path d={PATHS[12]} fill="#ed6d48" />
        <path d={PATHS[13]} fill="#eda18b" />
        <path d={PATHS[14]} fill="none" stroke="#000000" />
        <path d={PATHS[15]} fill="#a5a4a2" stroke="#000000" />
        <path d={PATHS[16]} fill="#a5a4a2" stroke="#000000" />
        <path d={PATHS[17]} fill="#fff0b1" stroke="#000000" />
        <path d={PATHS[18]} fill="#fff0b1" stroke="#000000" />
        <path d={PATHS[19]} fill="#fff0b1" stroke="#000000" />
      </g>
      {/* === Wire: substation to house (always pulses yellow) === */}
      <path
        d={PATHS[22]}
        className={`house-scene__wire ${gridOverloaded ? 'house-scene__wire--red-pulse' : 'house-scene__wire--yellow-pulse'}`}
        stroke="#101010"
      />
      {/* === Wire: neighbour (pulses red when grid overloaded) === */}
      <path
        d={PATHS[21]}
        className={`house-scene__wire ${gridOverloaded ? 'house-scene__wire--red-pulse' : 'house-scene__wire--yellow-pulse'}`}
        stroke="#101010"
      />
      {/* === Wire: charger to car (always visible, pulses red when charging) === */}
      <path
        d={PATHS[20]}
        className={`house-scene__wire${effectiveCharging ? ' house-scene__wire--red-pulse' : ''}`}
        fill="#000000"
        stroke="#101010"
      />
      {/* === Car (visible when carPresent, multi-coloured) === */}
      {carPresent && (
        <g>
          <path d={PATHS[23]} fill="#000000" />
          <path d={PATHS[24]} fill="#000000" />
          <path d={PATHS[25]} fill="#000000" />
          <path d={PATHS[26]} fill="#ffbf17" />
          <path d={PATHS[27]} fill="#c5eaff" />
          <path d={PATHS[28]} fill="#836212" />
          <path d={PATHS[29]} fill="#836212" />
          <path d={PATHS[30]} fill="#836212" />
          <path d={PATHS[31]} fill="#3a5430" />
          <path d={PATHS[32]} fill="#000000" />
          <path d={PATHS[33]} fill="#c5eaff" />
          <path d={PATHS[34]} fill="#41c377" />
          <path d={PATHS[35]} fill="#41c377" />
          <path d={PATHS[36]} fill="#000000" stroke="#000000" />
        </g>
      )}
      {/* === Substation (static, multi-coloured) === */}
      <g>
        <path d={PATHS[37]} fill="#000000" />
        <path d={PATHS[38]} fill="#a77b15" />
        <path d={PATHS[39]} fill="#a77b15" />
        <path d={PATHS[40]} fill="#ffbf17" />
        <path d={PATHS[41]} fill="#836212" />
        <path d={PATHS[42]} fill="#ffbf17" />
        <path d={PATHS[43]} fill="#a5a4a2" />
        <path d={PATHS[44]} fill="none" stroke="#101010" />
        <path d={PATHS[45]} fill="#a5a4a2" stroke="#101010" />
      </g>
      {/* === House structure (static, multi-coloured) === */}
      <g>
        <path d={PATHS[46]} fill="#000000" />
        <path d={PATHS[47]} fill="none" stroke="#000000" />
        <path d={PATHS[48]} fill="#836212" />
        <path d={PATHS[49]} fill="#a77b15" />
        <path d={PATHS[50]} fill="none" stroke="#000000" />
        <path d={PATHS[51]} fill="#d17157" stroke="#000000" />
        <path d={PATHS[52]} fill="none" stroke="#000000" />
        <path d={PATHS[53]} fill="#eda18b" stroke="#000000" />
        <path d={PATHS[54]} fill="#eda18b" stroke="#000000" />
        <path d={PATHS[55]} fill="#7c7979" stroke="#000000" />
      </g>
      {/* === House windows === */}
      {/* Window frame (always black) */}
      <path d={PATHS[56]} fill="#000000" />

      {/* Window panes 0-7 (toggle between black and warm yellow #fff0b1) */}
      {PATHS.slice(57, 65).map((d, i) => (
        <path
          key={`window-${i}`}
          d={d}
          data-window={i}
          className={litWindows.includes(i) ? 'house-scene__window--lit' : ''}
          fill={litWindows.includes(i) ? '#fff0b1' : '#000000'}
        />
      ))}
      {/* Neighbourhood window details (static) */}
      <g>
        <path d={PATHS[65]} fill="#fff0b1" />
        <path d={PATHS[66]} fill="#000000" />
        <path d={PATHS[67]} fill="#fff0b1" />
        <path d={PATHS[68]} fill="#000000" />
        <path d={PATHS[69]} fill="#fff0b1" />
        <path d={PATHS[70]} fill="#000000" />
        <path d={PATHS[71]} fill="#fff0b1" />
        <path d={PATHS[72]} fill="#000000" />
      </g>
    </svg>
  )
}

export default HouseScene
